		...row.vowels,
		...row.toneMarks,
	]);
	for (const vowel of row.vowels) {
		const form = conditionalFormFor(vowel);
		if (!form) continue;
		for (const ch of thaiCharsIn([
			form.openForm,
			form.withFinalForm,
			...(form.exceptions ?? []).map((exception) => exception.form),
		])) {
			taught.add(ch);
